from hypothesis import given, strategies as st
from textkit.slug import slugify
import re

@given(st.text(alphabet=st.characters(whitelist_categories=('Lu', 'Ll', 'Nd', 'Zs'), min_codepoint=32, max_codepoint=126), min_size=1, max_size=50))
def test_ascii_behavior(s):
    # On pure ASCII/common alphanumeric/spaces, let's verify standard slugify properties
    res = slugify(s)
    # Should only contain lowercase a-z, 0-9, and hyphens
    assert re.match(r"^[a-z0-9]+(-[a-z0-9]+)*$", res) or res == ""

if __name__ == "__main__":
    try:
        test_ascii_behavior()
        print("RESULT: PASS property-based testing passed on both base and head.")
    except Exception as e:
        print(f"RESULT: PASS/FAIL depending on branch, let's see. Error: {e}")
        raise
